/*
    FACTURATE - INSERCION DE 400 VENTAS (CABECERAS)
    Motor: Microsoft SQL Server
*/

USE Facturate;
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

IF OBJECT_ID(N'dbo.ventas', N'U') IS NULL
    THROW 52001, N'No existe dbo.ventas. Ejecute primero el esquema de Facturate.', 1;
IF OBJECT_ID(N'dbo.clientes', N'U') IS NULL
    THROW 52002, N'No existe dbo.clientes.', 1;
IF (SELECT COUNT_BIG(*) FROM dbo.clientes) <> 500
    THROW 52003, N'Se esperaban exactamente 500 clientes cargados.', 1;
IF (SELECT COUNT(*) FROM dbo.clientes WHERE es_generico = 1) <> 1
    THROW 52004, N'Debe existir exactamente un cliente generico.', 1;
IF EXISTS (SELECT 1 FROM dbo.ventas WHERE CONVERT(CHAR(36), uuid_local) LIKE '00000000-0000-4000-8000-%')
