        (CONVERT(UNIQUEIDENTIFIER, N'00000000-0000-4000-8000-000000000396'), N'CC', N'584548212', CONVERT(BIT, 0), CONVERT(DATETIME2(0), N'2026-08-09T15:56:13', 126)),
        (CONVERT(UNIQUEIDENTIFIER, N'00000000-0000-4000-8000-000000000397'), N'CC', N'1192986506', CONVERT(BIT, 0), CONVERT(DATETIME2(0), N'2026-05-07T17:59:15', 126)),
        (CONVERT(UNIQUEIDENTIFIER, N'00000000-0000-4000-8000-000000000398'), N'CC', N'853991649', CONVERT(BIT, 0), CONVERT(DATETIME2(0), N'2026-09-23T10:33:04', 126)),
        (CONVERT(UNIQUEIDENTIFIER, N'00000000-0000-4000-8000-000000000399'), N'CC', N'732045082', CONVERT(BIT, 0), CONVERT(DATETIME2(0), N'2026-09-23T10:35:42', 126)),
        (CONVERT(UNIQUEIDENTIFIER, N'00000000-0000-4000-8000-000000000400'), N'CE', N'362280523', CONVERT(BIT, 0), CONVERT(DATETIME2(0), N'2026-06-14T19:15:54', 126))
    ) AS origen (uuid_local, tipo_documento, numero_documento, es_generico, fecha_venta)
    INNER JOIN dbo.clientes AS c
        ON
        (
            origen.es_generico = 1
            AND c.es_generico = 1
            AND c.activo = 1
        )
        OR
        (
            origen.es_generico = 0
            AND c.es_generico = 0
            AND c.activo = 1
            AND c.tipo_documento = origen.tipo_documento
            AND c.numero_documento = origen.numero_documento
        );

    IF @@ROWCOUNT <> 400
        THROW 52006, N'No se insertaron las 400 ventas. Verifique que todos los clientes fuente existan una sola vez.', 1;

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
        ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO

-- Validacion: 400 cabeceras de venta, inicialmente en estado BORRADOR.
SELECT
    COUNT_BIG(*) AS ventas_insertadas,
    SUM(CASE WHEN estado_venta = 'BORRADOR' THEN 1 ELSE 0 END) AS ventas_pendientes_de_detalles,
    MIN(fecha_venta) AS primera_fecha,
    MAX(fecha_venta) AS ultima_fecha
FROM dbo.ventas
WHERE CONVERT(CHAR(36), uuid_local) LIKE '00000000-0000-4000-8000-%';
GO
